THOUGHT: The `systemClock` looks fine. Let me create a simple test program to reproduce the issue described in the PR description to confirm the problem.

```bash
cat <<'EOF' > test_panic.go
package main

import (
    "context"
    "time"
    "github.com/allegro/bigcache/v3"
)

func main() {
    config := bigcache.DefaultConfig(time.Minute)
    cache, err := bigcache.New(context.Background(), config)
    if err != nil {
        panic(err)
    }

    // This will panic with nil pointer dereference according to the issue
    cache.Set("test", []byte("value"))
    println("Successfully set value without panic")
}
EOF
```

